mapper.select:
SELECT a.*, count(*) over() AS ttl_no, b.intg_cd_dp_val_desc AS que_stt_nm, c.usr_nm AS que_usr_nm, c.usr_eml AS que_usr_eml, d.usr_nm AS ans_usr_nm, d.usr_eml AS ans_usr_eml, count(*) over() + 1 - ROW_NUMBER() over(
ORDER BY a.${orderByField} DESC
ORDER BY a.cre_dt DESC, a.que_id
) as no FROM que_mgmt a LEFT JOIN com_intg_cd_dtl b ON ( b.intg_cd = 'CD00010' AND a.que_sts_cd = b.intg_cd_val_ctnt ) LEFT JOIN usr_mgmt c ON ( a.que_usr_id = c.usr_id ) LEFT JOIN usr_mgmt d ON ( a.ans_usr_id = d.usr_id ) WHERE 1=1
AND UPPER(a.que_tit) LIKE #{queTit}
AND a.que_usr_id = #{queUsrId}
ORDER BY a.${orderByField} DESC
ORDER BY a.cre_dt DESC, a.que_id
OFFSET ${offset}
LIMIT ${limit}
